// ─────────────────────────────────────────────────────────────
// EDIT ME — your qualification criteria + reply instructions.
// This is the ONLY probabilistic step; everything else is deterministic.
// ─────────────────────────────────────────────────────────────
const SYSTEM_PROMPT = `You are a lead-qualification assistant for <YOUR COMPANY>.
Read the inbound email and decide if the sender is a QUALIFIED sales lead.

QUALIFY (qualified=true) only when ALL of these hold:
- The sender shows genuine interest in what we offer: <DESCRIBE YOUR OFFER>
- They look like a real prospect / decision-maker (not a job seeker, recruiter, vendor pitch, or spam)
- There is a concrete need or question we can help with

DISQUALIFY (qualified=false) when the email is an auto-reply, out-of-office,
unsubscribe request, newsletter, spam, or clearly not a buying signal.

When qualified, write the reply following these instructions:
- Warm, concise, professional; reference their specific message
- <YOUR CALL TO ACTION — e.g. propose a 15-minute call this week, or ask 1-2 qualifying questions>
- Sign off as <YOUR NAME>, <YOUR COMPANY>
- NEVER invent pricing, features, timelines, or commitments you are unsure about

Return STRICT JSON only (no markdown, no prose), exactly:
{"qualified": true|false, "reason": "<one short sentence>", "reply": "<full reply text, or empty string if not qualified>"}`;
// ─────────────────────────────────────────────────────────────

const msg = $input.item.json;

function b64(data) {
  return Buffer.from(String(data).replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8');
}
function decodeBody(payload) {
  if (!payload) return '';
  if (payload.mimeType === 'text/plain' && payload.body && payload.body.data) return b64(payload.body.data);
  if (payload.body && payload.body.data && !payload.parts) return b64(payload.body.data);
  if (payload.parts) {
    for (const p of payload.parts) {
      if (p.mimeType === 'text/plain' && p.body && p.body.data) return b64(p.body.data);
    }
    for (const p of payload.parts) {
      const t = decodeBody(p);
      if (t) return t;
    }
  }
  return '';
}

const headers = {};
(msg.payload && msg.payload.headers ? msg.payload.headers : []).forEach(h => {
  headers[h.name.toLowerCase()] = h.value;
});

let body = decodeBody(msg.payload);
if (!body) body = msg.text || msg.snippet || '';
body = body.slice(0, 6000); // cap tokens

const from = headers['from'] || msg.from || '';
const subject = headers['subject'] || msg.subject || '';

return {
  json: {
    from,
    subject,
    body,
    threadId: msg.threadId || '',
    messageId: msg.id || '',
    system: SYSTEM_PROMPT,
    userContent: `FROM: ${from}\nSUBJECT: ${subject}\n\nBODY:\n${body}`
  }
};

const resp = $input.item.json;
const prep = $('Prepare & Build Prompt').item.json;

let text = '';
try { text = resp.content[0].text; } catch (e) { text = resp.text || ''; }
text = String(text).trim()
  .replace(/^```json/i, '')
  .replace(/^```/, '')
  .replace(/```$/, '')
  .trim();

let parsed;
try { parsed = JSON.parse(text); }
catch (e) { parsed = { qualified: false, reason: 'Could not parse model output', reply: '' }; }

return {
  json: {
    from: prep.from,
    subject: prep.subject,
    threadId: prep.threadId,
    messageId: prep.messageId,
    qualified: parsed.qualified === true,
    reason: parsed.reason || '',
    reply: parsed.reply || ''
  }
};
